<script setup lang="ts">
import {ref,computed,watch} from 'vue'
import {locale,message} from './i18n'
import {api} from './api'
import FieldHint from './FieldHint.vue'
import CopyId from './CopyId.vue'
import TableToolbar from './TableToolbar.vue'
const l=(a:string,b:string)=>locale.value==='ar'?b:a
const names:Record<string,[string,string]>={connectors:['Connectors','الموصلات'],webhooks:['Webhooks','الأحداث الواردة'],logs:['Outbound logs','سجل الاتصالات الصادرة'],'webhook-deliveries':['Webhook deliveries','سجل الأحداث الواردة'],slug:['Slug','رمز المسار'],name:['Name','الاسم'],site_id:['Site ID (optional)','معرّف الموقع (اختياري)'],connector_id:['Connector ID (optional)','معرّف الموصل (اختياري)'],base_url:['Base URL','عنوان الخدمة'],health_path:['Health path','مسار الفحص'],auth_type:['Authentication','المصادقة'],auth_header_name:['API key header','ترويسة مفتاح الخدمة'],credentials:['New credential','بيانات اعتماد جديدة'],timeout_seconds:['Timeout (seconds)','مهلة الطلب بالثواني'],max_retries:['Retries','عدد المحاولات'],active:['Active','نشط'],signature_header:['Signature header','ترويسة التوقيع'],timestamp_header:['Timestamp header','ترويسة الوقت'],tolerance_seconds:['Time tolerance (seconds)','سماحية الوقت بالثواني'],method:['Method','الطريقة'],path:['Resource','المورد'],status_code:['HTTP status','حالة HTTP'],duration_ms:['Latency (ms)','المدة بالمللي ثانية'],error_code:['Error','رمز الخطأ'],created_at:['Created','وقت الإنشاء'],delivery_id:['Delivery ID','معرّف الحدث'],received_at:['Received','وقت الاستلام'],status:['Status','الحالة'],connector__slug:['Connector','الموصل'],endpoint__slug:['Endpoint','نقطة الاستقبال']}
const label=(k:string)=>names[k]?l(...names[k]):k
const tab=ref('connectors'),page=ref(1),size=ref(10),q=ref(''),count=ref(0),rows=ref<any[]>([]),edit=ref<any>(),note=ref(''),secret=ref(''),busy=ref(false)
const hook=computed(()=>tab.value==='webhooks'),config=computed(()=>hook.value||tab.value==='connectors')
const fields=computed(()=>['slug','name','site_id',...(hook.value?['connector_id','signature_header','timestamp_header','tolerance_seconds']:['base_url','health_path','auth_type','auth_header_name','credentials','timeout_seconds','max_retries']),'active'])
const cols=computed(()=>config.value?['slug','name','active']:tab.value==='logs'?['connector__slug','method','path','status_code','duration_ms','error_code','created_at']:['endpoint__slug','delivery_id','status','received_at'])
const numeric=['site_id','connector_id','timeout_seconds','max_retries','tolerance_seconds']
const root='/platform/v1/integrations/'
let serial=0
async function load(){const n=++serial;try{const d=await api<any>(root+tab.value+'?'+new URLSearchParams({search:q.value,page:String(page.value),page_size:String(size.value)}));if(n===serial){rows.value=d.results;count.value=d.count}}catch(e){if(n===serial)note.value=message(e)}}
watch([tab,q,page,size],load,{immediate:true})
function switchTo(k:string){tab.value=k;page.value=1;q.value='';edit.value=null;note.value='';secret.value='';rows.value=[]}
function form(r?:any){secret.value='';edit.value=r?{...r,credentials:''}:{slug:'',name:'',site_id:null,active:true,base_url:'',health_path:'/',auth_type:'none',auth_header_name:'Authorization',timeout_seconds:10,max_retries:2,signature_header:'X-Webhook-Signature',timestamp_header:'X-Webhook-Timestamp',tolerance_seconds:300}}
async function save(){busy.value=true;try{const d={...edit.value};for(const k of numeric)if(d[k]==='')d[k]=null;const r=await api<any>(root+tab.value+(d.id?'/'+d.slug:''),d.id?'PATCH':'POST',d);secret.value=r.signing_secret||'';edit.value=null;note.value=l('Saved','تم الحفظ');await load()}catch(e){note.value=message(e)}finally{busy.value=false}}
async function action(r:any){if(hook.value&&!confirm(l('Replace signing secret?','استبدال سر التوقيع؟')))return;busy.value=true;try{const d=await api<any>(root+tab.value+'/'+r.slug+'/'+(hook.value?'rotate-secret':'test'),'POST',{revision:r.revision});secret.value=d.signing_secret||'';note.value=hook.value?l('Secret rotated','تغير سر التوقيع'):'HTTP '+d.status+' · '+d.duration_ms+' ms';await load()}catch(e){note.value=message(e)}finally{busy.value=false}}
const callback=(slug:string)=>location.origin+'/api/webhooks/v1/'+slug+'/'
</script>
<template><section class="stack"><h1>{{l('Integrations & Webhooks','التكاملات والأحداث الواردة')}}</h1><nav class="actions"><button v-for="k in ['connectors','webhooks','logs','webhook-deliveries']" :disabled="busy" :aria-pressed="tab===k" @click="switchTo(k)">{{label(k)}}</button></nav><p v-if="note" role="status">{{note}}</p><aside v-if="secret" class="panel">{{l('Copy signing secret now','انسخ سر التوقيع الآن')}} <CopyId :value="secret"/> <button @click="secret=''">{{l('Dismiss','إغلاق')}}</button></aside>
<button v-if="config&&!edit" @click="form()">{{l('Create','إنشاء')}}</button>
<form v-if="edit" class="panel gateway-form" @submit.prevent="save"><div v-for="f in fields" :key="f" :class="{'gateway-active':f==='active'}"><div class="gateway-caption"><label :for="'gw-'+f">{{label(f)}}</label><FieldHint :label="label(f)" :hint-key="'gateway.'+f" :required="['slug','name','base_url'].includes(f)"/></div><select :id="'gw-'+f" v-if="f==='auth_type'" v-model="edit[f]"><option v-for="v in ['none','bearer','api_key_header','basic']">{{v}}</option></select><input :id="'gw-'+f" v-else-if="f==='active'" type="checkbox" v-model="edit[f]"><input :id="'gw-'+f" v-else v-model="edit[f]" :type="numeric.includes(f)?'number':f==='credentials'?'password':'text'" :required="['slug','name','base_url'].includes(f)" :disabled="f==='slug'&&edit.id"></div><div class="gateway-actions"><button :disabled="busy">{{l('Save','حفظ')}}</button> <button type="button" @click="edit=null">{{l('Cancel','إلغاء')}}</button></div></form>
<TableToolbar :page="page" :size="size" :count="count" :query="q" @search="q=$event;page=1" @size="size=$event;page=1" @page="page=$event"/><div class="table-scroll"><table><thead><tr><th v-for="k in cols">{{label(k)}}</th><th v-if="config">{{l('Actions','الإجراءات')}}</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td v-for="k in cols">{{k==='active'?(r[k]?l('Yes','نعم'):l('No','لا')):r[k]}}</td><td v-if="config"><button @click="form(r)">{{l('Edit','تعديل')}}</button> <button :disabled="busy" @click="action(r)">{{hook?l('Rotate secret','تغيير سر التوقيع'):l('Test connection','اختبار الاتصال')}}</button><CopyId v-if="hook" :value="callback(r.slug)"/></td></tr></tbody></table></div></section></template>
